using UnityEngine;
using UnityEditor;
using System;
using System.Linq;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            r.Log("page=" + s.Page + " intro=" + s.data.introAccepted + " skip=" + s.data.tutorialSkipped + " first=" + s.data.firstFloorRecorded + " notes=" + s.data.firstNotesReviewed + " evidence=" + s.InspectionCount + " position=" + s.movement.transform.position + " save=" + s.SavePath + " objective=" + s.CurrentObjective);
            foreach (var x in UnityEngine.Object.FindObjectsByType<InvestigationInteractable>(FindObjectsInactive.Exclude, FindObjectsSortMode.None).Where(x => x.evidenceId == "phone" || x.evidenceId == "slide" || x.evidenceId == "ha"))
                r.Log(x.evidenceId + " " + x.transform.position);
        }
    }
}

